    def dinic(source, sink, capacity, n_nodes):
        INF = float('inf')
        total_flow = 0
        adj = [[] for _ in range(n_nodes)]

        for i in range(n_nodes):
            for j in range(n_nodes):
                if capacity[i][j] > 0:
                    adj[i].append(j)

        while True:
            level = [-1] * n_nodes
            level[source] = 0
            queue = [source]

            while queue:
                u = queue.pop(0)
                for v in adj[u]:
                    if capacity[u][v] > 0 and level[v] < 0:
                        level[v] = level[u] + 1
                        queue.append(v)

            if level[sink] < 0:
                break

            ptr = [0] * n_nodes

            def dfs(u, flow):
                if flow == 0 or u == sink:
                    return flow
                for i in range(ptr[u], len(adj[u])):
                    ptr[u] = i
                    v = adj[u][i]
                    if level[v] == level[u] + 1 and capacity[u][v] > 0:
                        pushed = dfs(v, min(flow, capacity[u][v]))
                        if pushed > 0:
                            capacity[u][v] -= pushed
                            capacity[v][u] += pushed
                            return pushed
                return 0

            while True:
                pushed = dfs(source, INF)
                if pushed == 0:
                    break
                total_flow += pushed

        return total_flow

    for p in all_primes:
        source = 0
        sink = n + 1
        n_nodes = n + 2
        capacity = [[0] * n_nodes for _ in range(n_nodes)]

        for i in range(n):
            if i in prime_counts and p in prime_counts[i]:
                count = prime_counts[i][p]
                idx = i + 1
                # Position i+1
                if idx % 2 == 1:
                    capacity[source][idx] = count
                    capacity[idx][source] = 0
                else:
                    capacity[idx][sink] = count
                    capacity[sink][idx] = 0

        for u, v in edges:
            u1 = u + 1
            v1 = v + 1
            if u1 % 2 != v1 % 2:
                # This is a valid good pair connection (different parity)
                u_count = prime_counts[u].get(p, 0) if u in prime_counts else 0
                v_count = prime_counts[v].get(p, 0) if v in prime_counts else 0
                cap = min(u_count, v_count)
                capacity[u1][v1] = cap
                capacity[v1][u1] = 0
                capacity[u1][u1] += cap
                capacity[v1][v1] += cap if cap else 0

        total_ops += dinic(source, sink, capacity, n_nodes)

