Looking at this problem, I need to find the minimum cost to make all elements have a GCD > 1. The key insight is:

1. We can remove ONE segment (contiguous subsequence) paying m*a coins
2. We can change ONE element by at most 1, paying b coins per change
3. Operations can each be used at most once (and optionally not used at all)

The strategy is:
- For each candidate divisor g (from prime factors of ai, ai-1, ai+1), calculate minimum cost
- For a fixed g, each element can be:
  - Divisible as-is (cost 0)
  - Made divisible with ±1 change (cost b)
  - Cannot be made divisible (must be removed)
- Find optimal segment to remove covering problematic elements

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    arr = list(map(int, lines[1].split()))

    INF = float('inf')

    def get_prime_factors(x):
        """Get all prime factors of x"""
        factors = set()
        d = 2
        while d * d <= x:
            if x % d == 0:
                factors.add(d)
                while x % d == 0:
                    x //= d
            d += 1
        if x > 1:
            factors.add(x)
        return factors

    # Collect candidate divisors from all elements and their neighbors
    candidates = set()
    for x in arr:
        candidates.update(get_prime_factors(abs(x)))
        if x > 1:
            candidates.update(get_prime_factors(abs(x - 1)))
        if x + 1 <= 2000000000:
            candidates.update(get_prime_factors(abs(x + 1)))

    # Handle small special case
    if n == 1:
        # Single element - check if it can become divisible by any small prime
        costs = float('inf')
        for prime in [2, 3, 5, 7]:
            if arr[0] == prime:
                costs = 0
            elif arr[0] % prime == 0:
                costs = 0
            elif abs(arr[0] - prime) <= 1:
                costs = min(costs, b)
            elif (arr[0] + 1) >= prime:
                d = (arr[0] - prime)
                if d == 0 or d == 1 or d == prime - 1:
                    costs = min(costs, b)
        return str(max(0, costs))

    min_total = INF

    # Option 1: No removal, just change elements as needed
    all_divordable = True
    total_change_cost = 0
    for x in arr:
        dist = min(x % 2 if x % 2 != 0 else 0, 1)  # Check for div 2
        if dist > 1:
            all_divordable = False
            break
        # We'll check this after computing for each g

    def compute_cost_for_g(g):
        """Compute minimum cost for fixed divisor g"""
        costs = []
        bad_pos = []

        for i, x in enumerate(arr):
            remainder = x % g
            dist = min(remainder, g - remainder)
            if dist == 0:
                costs.append(0)
            elif dist == 1:
                costs.append(b)
            else:
                costs.append(INF)
                bad_pos.append(i)

        # Option 1: Try not removing any segment (all must be changeable)
        if INF not in costs:
            min_cost = sum(costs)

            # Option 2: Remove a segment to cover all bad positions
            if bad_pos:
                first_bad = min(bad_pos)
                last_bad = max(bad_pos)

                # Must remove segment [first_bad, last_bad] to cover all bad
                seg_len = last_bad - first_bad + 1

                if seg_len < n:
                    # Cost for remaining
                    keep_cost = sum(costs[i] for i in range(n) if i < first_bad or i > last_bad)
                    seg_cost = seg_len * a
                    min_cost = min(min_cost, seg_cost + keep_cost)
                else:
                    # Not valid, can't remove whole array
                    pass
        elif bad_pos:
            # Must remove segment covering all bad positions
            first_bad = min(bad_pos)
            last_bad = max(bad_pos)
            seg_len = last_bad - first_bad + 1
            if seg_len < n:
                keep_cost = sum(costs[i] for i in range(n) if i < first_bad or i > last_bad)
                seg_cost = seg_len * a
                min_cost = seg_cost + keep_cost
            else:
                return INF
        else:
            return INF  # Some elements cannot be made divisible

        return min_cost

    # Try each candidate divisor
    for g in candidates:
        if g == 1:
