    best_warehouse = [row[:] for row in warehouse]

    def can_place(r, c, shape):
        "Check if shape can be placed at position (r,c)"
        for dr, dc in shape:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < n and 0 <= nc < m):
                return False
            if warehouse[nr][nc] != '.':
                return False
        return True

    def place(r, c, shape, letter):
        "Place letter in cells"
        for dr, dc in shape:
