    def remove(r, c, shape):
        "Remove letter from cells"
        for dr, dc in shape:
            warehouse[r + dr][c + dc] = '.'

    def backtrack(letter_icons):
        "Backtracking search for optimal placement"
        if len(letter_icons) > best_count[0]:
            best_count[0] = len(letter_icons)
            best_warehouse = [list(row) for row in warehouse]

        # Find first empty cell
        for r in range(n):
