def solution(input_str):
    """
    Solve the turboplow packing problem.

    Args:
        input_str: Input string containing n and m

    Returns:
        Output string with count and warehouse layout
    """
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Four T-shape orientations (relative coordinates from placement top-left)
    t_shapes = [
        [(0, 0), (0, 1), (0, 2), (1, 1)],  # T pointing down (bar on top)
        [(2, 0), (1, 0), (1, 1), (1, 2)],  # T pointing up (bar on bottom)
        [(0, 0), (1, 0), (2, 0), (1, 1)],  # T pointing left (bar on left)
        [(0, 1), (0, 2), (1, 1), (2, 1)]   # T pointing right (bar on right)
    ]

    # Initialize empty warehouse
    warehouse = [['.'] * m for _ in range(n)]

    # Track best solution
    best_count = 0
    best_warehouse = []

    def can_place(r, c, shape):
        """Check if T-shape can be placed at position (r, c)"""
        for dr, dc in shape:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < n and 0 <= nc < m):
                return False
            if warehouse[nr][nc] != '.':
                return False
        return True

    def place_piece(r, c, shape, letter):
        """Mark warehouse cells with a letter"""
        for dr, dc in shape:
            warehouse[r + dr][c + dc] = letter

    def remove_piece(r, c, shape):
        """Clear warehouse cells back to '.'"""
        for dr, dc in shape:
            warehouse[r + dr][c + dc] = '.'

    def count_pieces():
        """Count how many letters are currently in the warehouse"""
        count = 0
        for row in warehouse:
            for cell in row:
                if 'A' <= cell <= 'Z':
                    count += 1
        return count

    def backtrack(letter_idx):
        """Backtracking DFS to find optimal placement"""
        nonlocal best_count, best_warehouse

        # Update best if we found better count
        current_count = count_pieces()
        if current_count > best_count:
            best_count = current_count
            best_warehouse = [row[:] for row in warehouse]

        # If we've used all letters, stop
        if chr(ord('A') + letter_idx - 1) > 'Z':
            return

        # Try to place more pieces, but limit search depth
        for r in range(n):
            for c in range(m):
                if warehouse[r][c] != '.':
                    continue

                # Try each T-shape orientation
                for i, shape in enumerate(t_shapes):
                    if not can_place(r, c, shape):
                        continue

                    letter = chr(ord('A') + letter_idx)
                    place_piece(r, c, shape, letter)
                    backtrack(letter_idx + 1)
                    remove_piece(r, c, shape)

    # Run backtracking
    backtrack(0)

    # Format output
    result_lines = [str(best_count)]
    result_lines.extend([''.join(row) for row in best_warehouse])
    return '\n'.join(result_lines) + '\n'


