Looking at this problem, I need to:
1. Find connected components of wires (wires are connected if they share a contact point)
2. Calculate minimum changes needed to make all wires form one connected component
3. Output the changes

The key insight is:
- Count connected components using Union-Find on contact points
- The answer is `max(0, num_components - 1)` where `num_components` is the number of connected components of points used in the edges
- When we need changes, we connect two different components by modifying one endpoint of an edge

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    t = int(lines[0])
    idx = 1
    output_lines = []

    for _ in range(t):
        if idx >= len(lines):
            break

        n = int(lines[idx])
        idx += 1

        # Read n edges
        edges = []
        points = set()
        for i in range(n):
            if idx >= len(lines):
                break
            x, y = map(int, lines[idx].split())
            idx += 1
            edges.append((x, y, i + 1))  # store wire index (1-based)
            points.add(x)
            points.add(y)

        # Case: 0 or 1 wire → no changes needed
        if n <= 1:
            output_lines.append("0")
            continue

        # Union-Find on points
        parent = {p: p for p in points}
        rank = {p: 0 for p in points}

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx != ry:
                if rank[rx] < rank[ry]:
                    parent[rx] = ry
                elif rank[rx] > rank[ry]:
                    parent[ry] = rx
                else:
                    parent[ry] = rx
                    rank[rx] += 1
            return True

        # Build components by processing all edges
        for x, y, _ in edges:
            union(x, y)

        # Count number of connected components
        roots = set(find(p) for p in points)
        num_components = len(roots)

        k = max(0, num_components - 1)
        output_lines.append(str(k))

        # If no changes needed
        if k == 0:
            continue

        # Need to connect components
        # Pick an edge and modify to connect two different components
        # Find an edge where both endpoints are in different components
        modified_edges = []
        for x, y, wire_idx in edges:
            root_x = find(x)
            root_y = find(y)
            if root_x != root_y:
                # Need to change one endpoint to connect components
                # Find another point in root_x's component
                member_x = x
                while member_x == x:
                    member_x = find(member_x)

                # Find a point in a different component
                other_root = None
                for other_root_candidate in roots:
                    if other_root_candidate != root_x:
                        other_root = other_root_candidate
                        break

                if other_root is None:
                    continue

                # Find a point in other_root's component
                member_y = None
                for p in points:
                    if find(p) == other_root:
                        member_y = p
                        break

                if member_y is not None and member_y != y:
                    modified_edges.append((wire_idx, x, member_y))

                if member_y is not None and member_y != x:
                    modified_edges.append((wire_idx, y, member_y))

                if modified_edges:
                    break

        # Output modifications
        for wire_idx, old_pt, new_pt in modified_edges:
            output_lines.append(f"{wire_idx} {old_pt} {new_pt}")

    return '\n'.join(output_lines)
